# Upyr shell widgets: fix text typed on the wrong keyboard layout at the
# prompt. Generated by `upyr shell-init bash`; load it from ~/.bashrc with
#   eval "$(upyr shell-init bash)"
# Bash 4 or newer is needed (macOS ships 3.2; zsh is its default shell).
#
#   Ctrl+X Ctrl+L  convert the whole command line
#   Ctrl+X L       convert the word before the cursor
#
# Set UPYR_NO_BINDINGS=1 before loading to bind the widgets yourself:
#   bind -x '"<keys>": upyr-convert-line'   /   upyr-convert-word

_upyr_bin=${UPYR_BIN:-@UPYR_BIN@}

# Converts $1 and leaves the result in $_upyr_reply. The installed layouts
# are preferred; the built-in table is the fallback.
_upyr_convert() {
  _upyr_reply=$("$_upyr_bin" convert --installed -- "$1" 2>/dev/null) ||
    _upyr_reply=$("$_upyr_bin" convert -- "$1" 2>/dev/null)
}

# READLINE_POINT counts bytes in bash 4 and characters from bash 5 on.
# _upyr_left: the text before the cursor; _upyr_point: the cursor after $1.
if (( BASH_VERSINFO[0] >= 5 )); then
  _upyr_left() { _upyr_out=${READLINE_LINE:0:READLINE_POINT}; }
  _upyr_point() { READLINE_POINT=${#1}; }
else
  _upyr_left() {
    local LC_ALL=C
    _upyr_out=${READLINE_LINE:0:READLINE_POINT}
  }
  _upyr_point() {
    local LC_ALL=C
    READLINE_POINT=${#1}
  }
fi

upyr-convert-line() {
  [[ -n $READLINE_LINE ]] || return 0
  _upyr_left
  local characters=${#_upyr_out}
  _upyr_convert "$READLINE_LINE" || return 1
  READLINE_LINE=$_upyr_reply
  # Layout conversion maps one character to one character, so the cursor
  # stays after the same number of characters.
  _upyr_point "${READLINE_LINE:0:characters}"
}

upyr-convert-word() {
  _upyr_left
  local left=$_upyr_out
  local right=${READLINE_LINE:${#left}}
  local trimmed=${left%"${left##*[![:space:]]}"}
  local spaces=${left:${#trimmed}}
  local word=${trimmed##*[[:space:]]}
  [[ -n $word ]] || return 0
  local prefix=${trimmed:0:${#trimmed}-${#word}}
  _upyr_convert "$word" || return 1
  left=$prefix$_upyr_reply$spaces
  READLINE_LINE=$left$right
  _upyr_point "$left"
}

if (( BASH_VERSINFO[0] < 4 )); then
  echo "upyr: the shell widgets need bash 4 or newer" >&2
elif [[ -z $UPYR_NO_BINDINGS ]]; then
  bind -x '"\C-x\C-l": upyr-convert-line'
  bind -x '"\C-xl": upyr-convert-word'
fi
